            ELSE
                almFalla := FALSE;
            END_IF;
    END_CASE;
ELSE
    bomba1 := FALSE;
    bomba2 := FALSE;
    almFalla := FALSE;
END_IF;

// Alternancia de estado en nueva demanda
IF NOT demandaAnterior AND demanda THEN
    IF estado = 1 THEN
        estado := 2;
    ELSE
        estado := 1;
    END_IF;
END_IF;

